u32 kvm_apic_get_timer_count(struct kvm_lapic *apic)
{
    u64 remaining;
    u32 count;

    if (!apic)
        return 0;

    if (!apic->timer.initial_count || !apic->timer.period)
        return 0;

    remaining = apic->base.time - apic->timer.base;
    if (remaining < 0)
        remaining = 0;

    count = (u32)((remaining % apic->timer.period) / apic->divide_count);

    return count;
}

u32 kvm_lapic_get_current_timer_count(struct kvm_lapic *apic)
{
    u64 period, remaining, bcycle;
    u32 count;

    if (!apic)
        return 0;

    if (apic->base.read(apic, APIC_TMICT) == 0 || apic->base.read(apic, APIC_TDCR) == 0)
        return 0;

    period = apic->base.read(apic, APIC_TMICT);
    period = (u64)((u64)period * (u64)APIC_BUS_CYCLE_NS) >> apic->base.read(apic, APIC_TDCR);

    remaining = apic->base.read(apic, APIC_TMICT) - apic->base.read(apic, APIC_TMCCT);

    if (remaining < 0)
        remaining = 0;

    bcycle = period % apic->base.read(apic, APIC_TDCR);
    count = (u32)(remaining / bcycle);

    return count;
}

u32 kvm_apic_get_current_timer_count(struct kvm_lapic *apic)
{
    u64 period;
    s64 remaining;

    if (!apic)
        return 0;

    if (apic->timer.initial_count == 0 || apic->timer.period == 0)
        return 0;

    remaining = apic->timer.tscdeadline - rdtsc();
    if (remaining < 0)
        remaining = 0;

    period = apic->timer.period;
    return (u32)((remaining % period) / (apic->divide_count));
}

u32 kvm_apic_get_timer_count(struct kvm_lapic *apic)
{
    u64 remaining_time;
    u64 period;
    u32 count;

    if (!apic)
        return 0;

    if (!apic->timer.initial_count || !apic->timer.period)
        return 0;

    remaining_time = apic->timer.initial_count - apic->timer.current_count;
    if (remaining_time > apic->timer.period)
        remaining_time = apic->timer.period;

    period = apic->timer.period;
    count = (u32)((remaining_time % period) / apic->timer.divide_count);

    return count;
}

u32 kvm_lapic_get_timer_count(struct kvm_lapic *apic)
{
    u64 period, delta;

    if (!apic)
        return 0;

    if (apic->base.sh_reg.timer.initial_count == 0 ||
        apic->base.sh_reg.timer.divider == 0)
        return 0;

    period = lapic_timer_period(apic);
    delta = apic->base.sh_reg.timer.initial_count * 1000LL;

    delta -= apic->base.sh_reg.timer.current_count * 1000LL;
    if (delta < 0)
        delta = 0;

    return (u32)(delta % period) / (apic->base.sh_reg.timer.divider);
}
